export default function f({ website, source, medium, campaign, term, campaignId, requestId }) {
  if (!requestId || !source || !medium || !campaign)
    throw Error("Enter a request ID, source, medium and campaign");
  const u = new URL(website);
  if (!["https:", "http:"].includes(u.protocol)) throw Error("Enter an HTTP website URL");
  for (const [k, v] of Object.entries({
    utm_source: source,
    utm_medium: medium,
    utm_campaign: campaign,
    utm_term: term,
    utm_content: campaignId,
  }))
    u.searchParams.set(k, v);
  return { url: u.href, key: "utm:" + requestId };
}

