export default async function f({ url, key, acknowledge, resolution }, ctx) {
  let s = await ctx.state.get(key);
  if (s?.status === "done") return { create: false, records: [{ fields: { URL: url } }] };
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect Airtable before reconciling pending create");
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { create: false, records: [{ fields: { URL: url } }] };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { create: true, records: [{ fields: { URL: url } }] };
}

