export default async function f({ key, url, records }, ctx) {
  if (records.length !== 1 || !records[0].id || records[0].fields.URL !== url)
    throw Error("Inspect Airtable record");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

