export default function f({ previous, report }) {
  let s = previous ?? { offset: 0, rows: [], count: null };
  if (report) {
    if (
      !Array.isArray(report.rows) ||
      !Number.isSafeInteger(report.rowCount) ||
      report.rowCount < 0 ||
      (s.count !== null && s.count !== report.rowCount)
    )
      throw Error("Invalid or changing GA report");
    const rows = [...s.rows, ...report.rows];
    if (rows.length > report.rowCount || (!report.rows.length && rows.length < report.rowCount))
      throw Error("Incomplete GA page");
    s = { offset: rows.length, rows, count: report.rowCount };
  }
  return { state: s, more: s.count === null || s.offset < s.count, offset: s.offset };
}

