export default async function f({ text, recipient, acknowledge, resolution }, ctx) {
  if (!text || !recipient || recipient.includes("YOUR_"))
    throw Error("Configure recipient and summary");
  const day = new Date().toISOString().slice(0, 10),
    key = "utm-report:" + day + ":" + recipient,
    s = await ctx.state.get(key);
  if (s?.status === "done") return { send: false, key, body: text, recipient };
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect Gmail before reconciling pending send");
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { send: false, key, body: text, recipient };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { send: true, key, body: text, recipient };
}

